// Textos visibles en el idioma activo (i18n/es|en/partCards.js); nombres oficiales sin traducir
i18n.applyText(PART_CARDS_LIST, 'partCards', ['description', 'adaptation', 'balance']);

/** id → carta */
export const PART_CARDS = Object.fromEntries(PART_CARDS_LIST.map((c) => [c.id, c]));

const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/['’]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const BY_KEY = new Map();
for (const c of PART_CARDS_LIST) BY_KEY.set(`${c.class}|${c.part}|${norm(c.name)}`, c);

/** Busca la carta por clase, tipo de parte y nombre de la parte (p. ej. 'beast', 'horn', 'Dual Blade'). */
// Nombres reales de la parte (API / genes) que el GDD escribe distinto o asigna a otra ranura.
const PART_ALIASES = {
  'bird|ears|owl': 'part_bird_ears_little_owl',
  'plant|eyes|confused': 'part_plant_eyes_confusion',
};

export function findPartCard(cls, part, name) {
  const alias = PART_ALIASES[`${String(cls || '').toLowerCase()}|${String(part || '').toLowerCase()}|${norm(name)}`];
  if (alias && PART_CARDS[alias]) return PART_CARDS[alias];
  const key = `${String(cls || '').toLowerCase()}|${String(part || '').toLowerCase()}|${norm(name)}`;
  if (BY_KEY.has(key)) return BY_KEY.get(key);
  // Nombres de la API con sufijos o variantes ("Nut Cracker", "Little Owl"…): coincidencia por prefijo
  const n = norm(name);
  for (const c of PART_CARDS_LIST) {
    if (c.class === String(cls).toLowerCase() && c.part === String(part).toLowerCase() && (n.startsWith(norm(c.name)) || norm(c.name).startsWith(n))) return c;
  }
  return null;
}

/** Campos que la interfaz lee de los hechizos (tooltip, pronóstico, cartas): se derivan de los efectos. */
export function withDisplayFields(card) {
  const c = { ...card };
  const dmg = c.effects.find((e) => e.type === 'damage');
  const heal = c.effects.find((e) => e.type === 'heal');
  const shield = c.effects.find((e) => e.type === 'shield');
  const push = c.effects.find((e) => e.type === 'push');
  if (dmg && dmg.hits !== 'spent') {
    const hits = typeof dmg.hits === 'number' ? dmg.hits : 1;
    c.baseMinDamage = dmg.min * hits;
    c.baseMaxDamage = dmg.max * hits;
  }
  if (heal) { c.baseMinHeal = heal.amount; c.baseMaxHeal = heal.amount; }
  if (shield) c.shieldAmount = shield.amount;
  if (push) c.pushDistance = push.distance;
  c.partIcon = `./assets/parts/${c.iconClass || c.class}-${c.part}.png`; // Mech/Dawn/Dusk no tienen icono propio
  // Ilustración original de la carta (assets/cards, 256 px); si no hay, el icono de la parte
  if (!c.icon) c.icon = c.art || c.partIcon;
  c.sound = c.sound || (dmg ? (c.maxRange > 1 ? 'bow' : 'melee') : (heal ? 'heal' : 'buff'));
  // Fase 5: las cartas que dan PA o PM a tu equipo se usan 1 vez por turno (si no, +2 PA por 1 PA = PA infinitos)
  const givesTempo = c.effects.some((e) => (e.type === 'resource' && ((e.pa || 0) > 0 || (e.pm || 0) > 0) && !/enem/i.test(e.target || ''))
    || (e.type === 'status' && e.status === 'energized'));
  if (givesTempo && c.castsPerTurn == null) c.castsPerTurn = 1;
  return c;
}

/** Hechizos listos para SPELLS_DB (con campos de interfaz). */
export const PART_SPELLS = Object.fromEntries(PART_CARDS_LIST.map((c) => [c.id, withDisplayFields(c)]));
